/* Types */
/**  Filter for `activity_list`. All fields optional; absent means "no constraint". */
export type ActivityFilter = {
	repoId: number | null,
	/**
	 *  Constrain to repos that belong to this group, resolved to membership
	 *  SERVER-SIDE via a `repo_groups` join (BL-NI-93). A group can contain many
	 *  repos, so this is deliberately a single group id rather than a
	 *  caller-supplied repo-id set: `activity::list`'s query is a compile-time
	 *  STATIC string (sqlx 0.9's `SqlSafeStr` forbids a dynamically built one),
	 *  which rules out a variable-length `repo_id IN (...)` clause for an
	 *  arbitrary `Vec<i64>` but admits a single static `EXISTS` subquery bound
	 *  once. Applied in the same `WHERE` as every other filter, so it constrains
	 *  BEFORE `LIMIT` - the same truncation-sentinel honesty `repo_id` already
	 *  gets. `None` applies no group constraint (matches every row, same as
	 *  every other filter here).
	 */
	groupId: number | null,
	actionType: string | null,
	status: string | null,
	limit: number | null,
};

/**
 *  One row of the `activity_records` audit trail. Maps verbatim to the schema
 *  (4.2): every git/check/update operation is recorded with its raw output.
 */
export type ActivityRecord = {
	id: number,
	repoId: number,
	timestamp: number,
	actionType: string,
	status: string,
	reasonCode: string | null,
	summary: string | null,
	commitRange: string | null,
	rawCommand: string | null,
	rawStdout: string | null,
	rawStderr: string | null,
	exitCode: number | null,
	durationMs: number | null,
};

/**
 *  The on-the-wire representation of an [`AppError`]. Every error the core sends
 *  across IPC reduces to this flat shape.
 */
export type AppErrorPayload = {
	/**  Stable machine code, e.g. `fs.path_missing`. */
	code: string,
	/**  Human-readable summary of what went wrong. */
	message: string,
	/**  Actionable guidance for resolving the error. */
	remediation: string,
	/**  Variant-specific detail (path, exit_code, stderr, cause, ...). */
	context: unknown | null,
};

/**  Which branches a repo is allowed to update. */
export type BranchPolicy = "default_branch_only" | "tracked_upstream_only" | "approved_branches" | "any_branch";

